figma.showUI(__html__,{width:360,height:650,themeColors:true});

const C={red:'#ee0033',redDark:'#bf0027',ink:'#1b1c1c',ink2:'#5a6675',ink3:'#8593a3',surface:'#ffffff',canvas:'#fbf9f9',subtle:'#f5f3f3',border:'#e6e9ee',borderStrong:'#c7cfda',success:'#006e0d',green:'#52c41a',greenBg:'#f6ffed',warning:'#fa8c16',warningText:'#d46b08',warningBg:'#fff7e6',danger:'#ba1a1a',dangerBg:'#fff2f0',muted:'#737373',purple:'#722ed1',blue:'#1677ff',cyan:'#13c2c2',pink:'#eb2f96',yellow:'#fadb14'};
const hex=h=>{const n=parseInt(h.slice(1),16);return{r:((n>>16)&255)/255,g:((n>>8)&255)/255,b:(n&255)/255}};
const paint=h=>({type:'SOLID',color:hex(h)});
const font=(style='Regular')=>({family:'Inter',style});
async function fonts(){await Promise.all(['Regular','Medium','Semi Bold','Bold'].map(style=>figma.loadFontAsync(font(style))));}
function tag(n,key){n.setPluginData('vht-run',RUN);n.setPluginData('vht-key',key);return n}
function auto(name,dir='VERTICAL'){const f=figma.createFrame();f.name=name;f.layoutMode=dir;f.primaryAxisSizingMode='AUTO';f.counterAxisSizingMode='AUTO';f.fills=[];return f}
function textNode(value,size=14,style='Regular',color=C.ink){const t=figma.createText();t.fontName=font(style);t.fontSize=size;t.characters=value;t.fills=[paint(color)];t.textAutoResize='WIDTH_AND_HEIGHT';return t}
function fixedText(value,width,size=14,style='Regular',color=C.ink,line=20){const t=textNode(value,size,style,color);t.textAutoResize='HEIGHT';t.resize(width,20);t.lineHeight={unit:'PIXELS',value:line};return t}
function ensurePage(name,key){let p=figma.root.children.find(x=>x.name===name);if(!p){p=figma.createPage();p.name=name}tag(p,key);return p}
function clearGenerated(page,prefix){for(const n of [...page.children])if(n.getPluginData('vht-key').startsWith(prefix))n.remove()}
function placeRight(page,node,gap=160){let x=80;for(const n of page.children)x=Math.max(x,n.x+n.width+gap);node.x=x;node.y=80}
function cardFrame(name,w,h){const f=auto(name);f.resize(w,h);f.primaryAxisSizingMode='FIXED';f.counterAxisSizingMode='FIXED';f.fills=[paint(C.surface)];f.strokes=[paint(C.border)];f.strokeWeight=1;f.cornerRadius=8;f.clipsContent=true;return f}

async function collection(name,mode='Value'){const all=await figma.variables.getLocalVariableCollectionsAsync();let c=all.find(x=>x.name===name);if(!c){c=figma.variables.createVariableCollection(name);c.renameMode(c.defaultModeId,mode)}return c}
async function variable(coll,name,type,value,scopes,syntax){const all=await figma.variables.getLocalVariablesAsync(type);let v=all.find(x=>x.name===name&&x.variableCollectionId===coll.id);if(!v)v=figma.variables.createVariable(name,coll,type);v.scopes=scopes;v.setValueForMode(coll.defaultModeId,value);if(syntax)v.setVariableCodeSyntax('WEB',syntax);return v}
async function buildFoundations(){await fonts();const primitives=await collection('Primitives'),colors=await collection('Color','Light'),dims=await collection('Dimensions');const prim={};for(const [name,val] of Object.entries(C))prim[name]=await variable(primitives,'color/'+name,'COLOR',hex(val),[],val);
  const sem=[['color/bg/canvas','canvas',['FRAME_FILL'],'var(--vht-surface-2)'],['color/bg/surface','surface',['FRAME_FILL','SHAPE_FILL'],'var(--vht-surface)'],['color/bg/subtle','subtle',['FRAME_FILL','SHAPE_FILL'],'var(--vht-surface-3)'],['color/text/primary','ink',['TEXT_FILL'],'var(--vht-ink)'],['color/text/secondary','ink2',['TEXT_FILL'],'var(--vht-ink-2)'],['color/text/muted','ink3',['TEXT_FILL'],'var(--vht-ink-3)'],['color/border/default','border',['STROKE_COLOR'],'var(--vht-border)'],['color/border/strong','borderStrong',['STROKE_COLOR'],'var(--vht-border-strong)'],['color/action/primary','red',['FRAME_FILL','SHAPE_FILL'],'var(--vht-red)']];
  for(const [n,p,s,css] of sem)await variable(colors,n,'COLOR',{type:'VARIABLE_ALIAS',id:prim[p].id},s,css);
  for(const [n,v,scope,css] of [['spacing/2xs',2,'GAP','2px'],['spacing/xs',4,'GAP','4px'],['spacing/sm',8,'GAP','8px'],['spacing/md',12,'GAP','12px'],['spacing/lg',16,'GAP','16px'],['spacing/xl',20,'GAP','20px'],['spacing/2xl',24,'GAP','24px'],['spacing/3xl',32,'GAP','32px'],['radius/sm',4,'CORNER_RADIUS','4px'],['radius/md',8,'CORNER_RADIUS','var(--vht-radius)'],['radius/lg',12,'CORNER_RADIUS','12px'],['radius/full',999,'CORNER_RADIUS','999px']])await variable(dims,n,'FLOAT',v,[scope],css);
  const styles=[['Heading/3',24,'Bold',32],['Body/Default',14,'Regular',22],['Body/Small',13,'Regular',20],['Label/Default',14,'Semi Bold',20],['Label/Small',12,'Semi Bold',18],['Statistic',30,'Regular',38]];
  const existing=await figma.getLocalTextStylesAsync();for(const [name,size,style,line] of styles){let s=existing.find(x=>x.name===name);if(!s)s=figma.createTextStyle();s.name=name;s.fontName=font(style);s.fontSize=size;s.lineHeight={unit:'PIXELS',value:line}}
  const effects=await figma.getLocalEffectStylesAsync();for(const [name,e] of [['Elevation/Card',{type:'DROP_SHADOW',color:{r:0,g:0,b:0,a:.04},offset:{x:0,y:1},radius:3,spread:0,visible:true,blendMode:'NORMAL'}],['Elevation/Card Hover',{type:'DROP_SHADOW',color:{r:0,g:0,b:0,a:.10},offset:{x:0,y:4},radius:16,spread:0,visible:true,blendMode:'NORMAL'}],['Focus/Brand',{type:'DROP_SHADOW',color:{...hex(C.red),a:.25},offset:{x:0,y:0},radius:0,spread:2,visible:true,blendMode:'NORMAL'}]]){let s=effects.find(x=>x.name===name);if(!s)s=figma.createEffectStyle();s.name=name;s.effects=[e]}
  const page=ensurePage('Foundations','page/foundations');clearGenerated(page,'docs/foundations');await figma.setCurrentPageAsync(page);const doc=tag(auto('VHT Foundations'),'docs/foundations');doc.paddingTop=48;doc.paddingRight=48;doc.paddingBottom=48;doc.paddingLeft=48;doc.itemSpacing=28;doc.fills=[paint(C.canvas)];doc.appendChild(textNode('VHT Foundations',32,'Bold'));doc.appendChild(fixedText('Nguồn chuẩn từ webapp/src/branding/tokens.css và webapp/src/theme.ts',900,14,'Regular',C.ink2,22));const sw=auto('Color tokens','HORIZONTAL');sw.itemSpacing=12;for(const [n,v] of Object.entries(C)){const item=auto(n);item.itemSpacing=6;const box=figma.createRectangle();box.resize(84,64);box.cornerRadius=8;box.fills=[paint(v)];item.appendChild(box);item.appendChild(textNode(n,11,'Medium'));item.appendChild(textNode(v,10,'Regular',C.ink3));sw.appendChild(item)}doc.appendChild(sw);page.appendChild(doc);doc.x=80;doc.y=80;return{page:page.id,frame:doc.id}}

const UBCK={primary:{50:'#BCFFE1',100:'#ACF1D2',200:'#90D4B7',300:'#75B99C',400:'#5B9E83',500:'#0F5A43',600:'#00513B',700:'#004431',800:'#003828',900:'#002C1F',950:'#002116'},secondary:{50:'#F8F8F8',100:'#F3F3F3',200:'#E1E1E1',300:'#C5C5C5',400:'#AAAAAA',500:'#909090',600:'#767676',700:'#5E5E5E',800:'#454745',900:'#2F312F',950:'#1B1B1B'},green:{50:'#C3FFCF',100:'#74FCA4',200:'#55DF8B',300:'#32C372',400:'#00A65B',500:'#00894A',600:'#00522A',700:'#00391B'},red:{50:'#FFEDEA',100:'#FFDAD6',200:'#FFB4AB',300:'#FF897D',400:'#FF5449',500:'#DE3730',600:'#BA1A1A',700:'#93000A'},orange:{50:'#fef6ee',100:'#ffedd5',200:'#fad2ae',300:'#f7b27a',400:'#f38844',500:'#EE671F',600:'#e04f16',700:'#c2410c'},sky:{50:'#f0f9ff',100:'#e0f2fe',200:'#bae6fd',300:'#7dd3fc',400:'#38bdf8',500:'#0ea5e9',600:'#0284c7',700:'#0369a1'},purple:{50:'#faf5ff',100:'#f3e8ff',200:'#e9d5ff',300:'#d8b4fe',400:'#c084fc',500:'#a855f7',600:'#9333ea',700:'#7e22ce'}};
const UBCK_FONTS={Regular:{family:'Roboto',style:'Regular'},Medium:{family:'Roboto',style:'Medium'},SemiBold:{family:'Roboto',style:'SemiBold'},Bold:{family:'Roboto',style:'Bold'},Mono:{family:'Roboto Mono',style:'Regular'}};
async function ubckFonts(){await fonts();const available=await figma.listAvailableFontsAsync();const pick=(family,candidates,fallback)=>{const found=available.find(x=>x.fontName.family===family&&candidates.includes(x.fontName.style));return found?found.fontName:fallback};UBCK_FONTS.Regular=pick('Roboto',['Regular'],font('Regular'));UBCK_FONTS.Medium=pick('Roboto',['Medium','Regular'],font('Medium'));UBCK_FONTS.SemiBold=pick('Roboto',['SemiBold','Semi Bold','Medium','Bold'],font('Semi Bold'));UBCK_FONTS.Bold=pick('Roboto',['Bold','SemiBold','Semi Bold'],font('Bold'));UBCK_FONTS.Mono=pick('Roboto Mono',['Regular'],UBCK_FONTS.Regular);await Promise.all(Object.values(UBCK_FONTS).map(x=>figma.loadFontAsync(x)))}
async function ubckCollection(name,modes=['Value']){if(name==='UBCK Semantic'){name='UBCK Semantic Light';modes=['Value']}const all=await figma.variables.getLocalVariableCollectionsAsync();let c=all.find(x=>x.name===name);if(!c){c=figma.variables.createVariableCollection(name);c.renameMode(c.defaultModeId,modes[0])}return c}
async function ubckVar(coll,name,type,values,scopes,css){const all=await figma.variables.getLocalVariablesAsync(type);let v=all.find(x=>x.name===name&&x.variableCollectionId===coll.id);if(!v)v=figma.variables.createVariable(name,coll,type);v.scopes=scopes;for(const [modeName,value] of Object.entries(values)){const mode=coll.modes.find(x=>x.name===modeName);if(mode)v.setValueForMode(mode.modeId,value)}if(css)v.setVariableCodeSyntax('WEB',`var(${css})`);return v}
async function buildUbckFoundations(){
  await ubckFonts();
  const primitives=await ubckCollection('UBCK Primitives');
  const semanticLight=await ubckCollection('UBCK Semantic Light');
  const semanticDark=await ubckCollection('UBCK Semantic Dark');
  const dims=await ubckCollection('UBCK Dimensions');
  const p={};
  for(const [family,scale] of Object.entries(UBCK)){
    for(const [step,value] of Object.entries(scale)){
      p[`${family}/${step}`]=await ubckVar(primitives,`color/${family}/${step}`,'COLOR',{Value:hex(value)},[],`--ubck-${family}-${step}`);
    }
  }
  const extras={white:'#ffffff',black:'#000000','surface/50':'#f2f2f2','surface/100':'#c2c2c2','surface/200':'#919191','surface/300':'#616161','surface/400':'#303030','surface/950':'#09090b'};
  for(const [name,value] of Object.entries(extras)){
    p[name]=await ubckVar(primitives,`color/${name}`,'COLOR',{Value:hex(value)},[],`--ubck-${name.replace('/','-')}`);
  }
  const alias=key=>({type:'VARIABLE_ALIAS',id:p[key].id});
  const sem=[
    ['color/bg/page',alias('white'),alias('surface/950'),['FRAME_FILL']],
    ['color/bg/surface',alias('white'),alias('secondary/900'),['FRAME_FILL','SHAPE_FILL']],
    ['color/bg/subtle',alias('secondary/50'),alias('secondary/800'),['FRAME_FILL','SHAPE_FILL']],
    ['color/text/primary',alias('black'),alias('white'),['TEXT_FILL']],
    ['color/text/secondary',alias('secondary/700'),alias('secondary/300'),['TEXT_FILL']],
    ['color/text/disabled',alias('secondary/500'),alias('secondary/600'),['TEXT_FILL']],
    ['color/border/default',alias('secondary/300'),alias('secondary/700'),['STROKE_COLOR']],
    ['color/action/primary',alias('primary/500'),alias('primary/400'),['FRAME_FILL','SHAPE_FILL','TEXT_FILL']],
    ['color/action/primary-hover',alias('primary/600'),alias('primary/300'),['FRAME_FILL','SHAPE_FILL']],
    ['color/status/success',alias('green/500'),alias('green/300'),['FRAME_FILL','SHAPE_FILL','TEXT_FILL']],
    ['color/status/info',alias('sky/500'),alias('sky/300'),['FRAME_FILL','SHAPE_FILL','TEXT_FILL']],
    ['color/status/warning',alias('orange/500'),alias('orange/300'),['FRAME_FILL','SHAPE_FILL','TEXT_FILL']],
    ['color/status/danger',alias('red/500'),alias('red/300'),['FRAME_FILL','SHAPE_FILL','TEXT_FILL']],
    ['color/status/help',alias('purple/500'),alias('purple/300'),['FRAME_FILL','SHAPE_FILL','TEXT_FILL']]
  ];
  for(const [name,light,dark,scopes] of sem){
    await ubckVar(semanticLight,name,'COLOR',{Value:light},scopes,`--ubck-${name.replaceAll('/','-')}`);
    await ubckVar(semanticDark,name,'COLOR',{Value:dark},scopes,`--ubck-dark-${name.replaceAll('/','-')}`);
  }
  const dimensions=[['spacing/2xs',2,'GAP'],['spacing/xs',4,'GAP'],['spacing/sm',8,'GAP'],['spacing/md',12,'GAP'],['spacing/lg',16,'GAP'],['spacing/xl',20,'GAP'],['spacing/2xl',24,'GAP'],['spacing/3xl',32,'GAP'],['radius/none',0,'CORNER_RADIUS'],['radius/xs',2,'CORNER_RADIUS'],['radius/sm',4,'CORNER_RADIUS'],['radius/md',6,'CORNER_RADIUS'],['radius/lg',8,'CORNER_RADIUS'],['radius/xl',12,'CORNER_RADIUS']];
  for(const [name,value,scope] of dimensions)await ubckVar(dims,name,'FLOAT',{Value:value},[scope],`--ubck-${name.replace('/','-')}`);
  const textStyles=[['UBCK/Display/L',72,80,'Bold'],['UBCK/Display/M',64,72,'Bold'],['UBCK/Display/S',48,56,'Bold'],['UBCK/Heading/L',32,38,'SemiBold'],['UBCK/Heading/M',24,30,'SemiBold'],['UBCK/Heading/S',20,28,'SemiBold'],['UBCK/Body/L',16,24,'Regular'],['UBCK/Body/M',14,20,'Regular'],['UBCK/Body/S',12,18,'Regular'],['UBCK/Number/L',24,30,'Medium'],['UBCK/Number/M',16,24,'Medium'],['UBCK/Number/S',12,18,'Medium']];
  const existingText=await figma.getLocalTextStylesAsync();
  for(const [name,size,line,style] of textStyles){let s=existingText.find(x=>x.name===name);if(!s)s=figma.createTextStyle();s.name=name;s.fontName=name.includes('/Number/')?UBCK_FONTS.Mono:UBCK_FONTS[style];s.fontSize=size;s.lineHeight={unit:'PIXELS',value:line}}
  const effectDefs=[['UBCK/Elevation/Overlay',{type:'DROP_SHADOW',color:{r:0,g:0,b:0,a:.1},offset:{x:0,y:4},radius:6,spread:-1,visible:true,blendMode:'NORMAL'}],['UBCK/Elevation/Modal',{type:'DROP_SHADOW',color:{r:0,g:0,b:0,a:.12},offset:{x:0,y:20},radius:25,spread:-5,visible:true,blendMode:'NORMAL'}],['UBCK/Elevation/Card',{type:'DROP_SHADOW',color:{r:0,g:0,b:0,a:.1},offset:{x:0,y:1},radius:3,spread:0,visible:true,blendMode:'NORMAL'}]];
  const existingEffects=await figma.getLocalEffectStylesAsync();
  for(const [name,effect] of effectDefs){let s=existingEffects.find(x=>x.name===name);if(!s)s=figma.createEffectStyle();s.name=name;s.effects=[effect]}
  const page=ensurePage('UBCK Foundations','page/ubck-foundations');
  await figma.setCurrentPageAsync(page);clearGenerated(page,'ubck/docs/foundations');
  const doc=tag(auto('UBCK Foundations'),'ubck/docs/foundations');doc.paddingTop=40;doc.paddingLeft=40;doc.paddingRight=40;doc.paddingBottom=40;doc.itemSpacing=24;doc.fills=[paint('#ffffff')];
  doc.appendChild(textNode('UBCK Design Foundations',32,'Bold'));doc.appendChild(fixedText('Nguồn: @khcn-core/theme 0.0.1-v21 · PrimeNG 21 · Light/Dark · Roboto',1100,14,'Regular',C.ink2,22));
  for(const family of ['primary','secondary','green','red','orange','sky','purple']){const section=auto(family,'HORIZONTAL');section.itemSpacing=8;for(const [step,value] of Object.entries(UBCK[family])){const sw=auto(`${family}/${step}`);sw.itemSpacing=4;const box=figma.createRectangle();box.resize(64,48);box.cornerRadius=6;box.fills=[paint(value)];sw.appendChild(box);sw.appendChild(textNode(step,9,'Medium'));section.appendChild(sw)}doc.appendChild(section)}
  page.appendChild(doc);doc.x=80;doc.y=80;
  return{page:page.id,frame:doc.id,collections:[primitives.id,semanticLight.id,semanticDark.id,dims.id],primitiveCount:Object.values(UBCK).reduce((n,x)=>n+Object.keys(x).length,0)+8,semanticCount:sem.length*2,textStyleCount:textStyles.length,effectStyleCount:effectDefs.length}
}

function ubckText(value,size=14,style='Regular',color='#000000'){const t=figma.createText();t.fontName=UBCK_FONTS[style]||UBCK_FONTS.Regular;t.fontSize=size;t.characters=value;t.fills=[paint(color)];t.textAutoResize='WIDTH_AND_HEIGHT';return t}
function ubckBoundPaint(vars,name,fallback){const v=vars[name];return v?figma.variables.setBoundVariableForPaint(paint(fallback),'color',v):paint(fallback)}
function ubckTextBound(value,size,style,vars,name,fallback){const t=ubckText(value,size,style,fallback);t.fills=[ubckBoundPaint(vars,name,fallback)];return t}
function ubckCompBase(family,key,name){const c=tag(figma.createComponent(),`ubck/component/${family.toLowerCase()}/${key}`);c.name=name;c.layoutMode='HORIZONTAL';c.primaryAxisSizingMode='AUTO';c.counterAxisSizingMode='AUTO';c.counterAxisAlignItems='CENTER';c.itemSpacing=8;c.paddingLeft=12;c.paddingRight=12;c.paddingTop=8;c.paddingBottom=8;c.cornerRadius=8;return c}
