  if(family==='Button'){c.fills=p.Variant==='Filled'?[primary]:[surface];c.strokes=[primary];c.appendChild(ubckTextBound('Button',fs,'Medium',vars,p.Variant==='Filled'?'color/bg/surface':'color/action/primary',p.Variant==='Filled'?'#ffffff':UBCK.primary[500]))}
  else if(family==='Input'||family==='Select'){c.resize(size==='Small'?220:size==='Large'?320:270,size==='Small'?34:size==='Large'?50:42);c.primaryAxisSizingMode='FIXED';c.primaryAxisAlignItems='SPACE_BETWEEN';c.appendChild(ubckTextBound(state==='Invalid'?'Giá trị không hợp lệ':'Nhập nội dung…',fs,'Regular',vars,state==='Disabled'?'color/text/disabled':'color/text/secondary',UBCK.secondary[600]));if(family==='Select')c.appendChild(ubckText('⌄',fs,'Medium',UBCK.secondary[700]));if(state==='Focus')c.strokes=[primary];if(state==='Invalid')c.strokes=[ubckBoundPaint(vars,'color/status/danger',UBCK.red[500])]}
  else if(family==='Checkbox'||family==='Radio'){c.fills=[];c.strokes=[];c.paddingLeft=0;c.paddingRight=0;const mark=family==='Checkbox'?figma.createRectangle():figma.createEllipse();mark.resize(20,20);mark.fills=p.Checked==='True'?[primary]:[surface];mark.strokes=[p.Checked==='True'?primary:border];if(family==='Checkbox')mark.cornerRadius=4;c.appendChild(mark);c.appendChild(ubckTextBound(family==='Checkbox'?'Checkbox':'Radio option',14,'Regular',vars,'color/text/primary','#000000'))}
  else if(family==='Toggle'){c.fills=[];c.strokes=[];c.paddingLeft=0;c.paddingRight=0;const track=figma.createFrame();track.resize(44,24);track.cornerRadius=12;track.fills=p.Checked==='True'?[primary]:[subtle];track.strokes=[border];const knob=figma.createEllipse();knob.resize(18,18);knob.x=p.Checked==='True'?22:3;knob.y=2;knob.fills=[surface];track.appendChild(knob);c.appendChild(track);c.appendChild(ubckTextBound('Toggle',14,'Regular',vars,'color/text/primary','#000000'))}
  else if(family==='Avatar'){c.fills=[];c.strokes=[];c.paddingLeft=0;c.paddingRight=0;const d=size==='Small'?32:size==='Large'?64:44;const av=auto('Avatar','HORIZONTAL');av.resize(d,d);av.primaryAxisSizingMode='FIXED';av.counterAxisSizingMode='FIXED';av.primaryAxisAlignItems='CENTER';av.counterAxisAlignItems='CENTER';av.cornerRadius=p.Shape==='Square'?8:d/2;av.fills=[primary];av.appendChild(ubckText('UB',size==='Small'?11:size==='Large'?20:14,'Medium','#ffffff'));c.appendChild(av)}
  else if(family==='Badge'||family==='Tag'){const tone={Success:[UBCK.green[100],UBCK.green[700]],Info:[UBCK.sky[100],UBCK.sky[700]],Warning:[UBCK.orange[100],UBCK.orange[700]],Danger:[UBCK.red[500],'#ffffff']}[p.Severity]||[UBCK.primary[100],UBCK.primary[700]];c.fills=[paint(tone[0])];c.strokes=[];c.cornerRadius=family==='Badge'?999:8;c.paddingTop=4;c.paddingBottom=4;c.appendChild(ubckText(family==='Badge'?'8':'Label',12,'Bold',tone[1]))}
  else if(family==='Card'){c.layoutMode='VERTICAL';c.resize(size==='Small'?220:size==='Large'?340:280,size==='Small'?120:size==='Large'?190:150);c.primaryAxisSizingMode='FIXED';c.counterAxisSizingMode='FIXED';c.itemSpacing=8;c.fills=p.Variant==='Filled'?[subtle]:[surface];c.appendChild(ubckTextBound('Card title',18,'Medium',vars,'color/text/primary','#000000'));const body=ubckTextBound('Supporting content and actions.',13,'Regular',vars,'color/text/secondary',UBCK.secondary[700]);body.textAutoResize='HEIGHT';body.resize(size==='Large'?300:size==='Small'?180:240,36);c.appendChild(body);c.appendChild(ubckTextBound('Action',12,'Medium',vars,'color/action/primary',UBCK.primary[500]))}
