async function run(type){if(type==='foundations')return buildFoundations();if(type==='components')return buildComponents();if(type==='screen-subsystems')return buildSubsystemScreen();if(type==='screen-users')return buildUsersScreen();if(type==='screen-org')return buildOrgScreen();if(type==='screen-permissions')return buildPermissionScreen();if(type==='screen-tasks')return buildTaskListScreen();if(type==='screen-task-create')return buildTaskCreateScreen();if(type==='screen-task-detail')return buildTaskDetailScreen();if(type==='screen-dossiers')return buildDossierListScreen();if(type==='screen-dossier-create')return buildDossierCreateScreen();if(type==='screen-dossier-detail')return buildDossierDetailScreen();if(type==='screen-worklist')return buildWorklistScreen();if(type==='screen-processes')return buildProcessCatalogScreen();if(type==='screen-process-create')return buildProcessCreateScreen();if(type==='screen-process-detail')return buildProcessDetailScreen();if(type==='screen-rule-scale')return buildRuleScaleScreen();if(type==='screen-integrations')return buildIntegrationsScreen();if(type==='all-system'){await buildFoundations();return buildComponents()}if(type==='all'){await buildFoundations();await buildComponents();await buildSubsystemScreen();await buildUsersScreen();await buildOrgScreen();await buildPermissionScreen();await buildTaskListScreen();await buildTaskCreateScreen();await buildTaskDetailScreen();await buildDossierListScreen();await buildDossierCreateScreen();await buildDossierDetailScreen();await buildWorklistScreen();await buildProcessCatalogScreen();await buildProcessCreateScreen();await buildProcessDetailScreen();await buildRuleScaleScreen();return buildIntegrationsScreen()}throw new Error('Unknown action '+type)}
async function dispatch(type){if(type==='ubck-foundations')return buildUbckFoundations();if(type==='ubck-components')return buildUbckComponents();if(type==='ubck-all'){await buildUbckFoundations();return buildUbckComponents()}return run(type)}
figma.ui.onmessage=async m=>{try{const result=await dispatch(m.type);figma.ui.postMessage({message:'Hoàn tất: '+m.type+' · '+JSON.stringify(result)})}catch(e){console.error(e);figma.ui.postMessage({error:true,message:'Lỗi: '+(e&&e.message?e.message:String(e))})}};
